190	ncnn::Mat ncnn_embedding::mean_pool(const ncnn::Mat& embeddings) const {
191	    int seq_len = embeddings.h;
192	    int dim = embeddings.w;
193	
194	    ncnn::Mat pooled(dim);
195	    pooled.fill(0.0f);
196	
197	    for (int i = 0; i < seq_len; ++i) {
198	        const float* row = embeddings.row(i);
199	        float* pooled_ptr = pooled;
200	        for (int j = 0; j < dim; ++j) {
201	            pooled_ptr[j] += row[j];
202	        }
203	    }
204	
205	    float scale = 1.0f / static_cast<float>(seq_len);
206	    float* pooled_ptr = pooled;
207	    for (int j = 0; j < dim; ++j) {
208	        pooled_ptr[j] *= scale;
209	    }
210	
211	    return pooled;
212	}
