214	ncnn::Mat ncnn_embedding::normalize(const ncnn::Mat& vec) const {
215	    int dim = vec.w;
216	    const float* ptr = vec;
217	
218	    float norm = 0.0f;
219	    for (int i = 0; i < dim; ++i) {
220	        norm += ptr[i] * ptr[i];
221	    }
222	    norm = std::sqrt(norm);
223	
224	    ncnn::Mat normalized(dim);
225	    float* out_ptr = normalized;
226	    if (norm > 1e-10f) {
227	        for (int i = 0; i < dim; ++i) {
228	            out_ptr[i] = ptr[i] / norm;
229	        }
230	    } else {
231	        for (int i = 0; i < dim; ++i) {
232	            out_ptr[i] = ptr[i];
233	        }
234	    }
235	
236	    return normalized;
237	}
