239	ncnn::Mat ncnn_embedding::preprocess_image(const std::vector<unsigned char>& image_data, int width, int height, int channels) const {
240	    ncnn::Mat output(image_size_, image_size_, 3);
241	
242	    float scale_x = static_cast<float>(width) / image_size_;
243	    float scale_y = static_cast<float>(height) / image_size_;
244	
245	    for (int y = 0; y < image_size_; ++y) {
246	        for (int x = 0; x < image_size_; ++x) {
247	            float src_x = x * scale_x;
248	            float src_y = y * scale_y;
249	
250	            int x0 = static_cast<int>(src_x);
251	            int y0 = static_cast<int>(src_y);
252	            int x1 = std::min(x0 + 1, width - 1);
253	            int y1 = std::min(y0 + 1, height - 1);
254	
255	            float dx = src_x - x0;
256	            float dy = src_y - y0;
257	
258	            for (int c = 0; c < 3; ++c) {
259	                int src_c = std::min(c, channels - 1);
260	                int idx00 = (y0 * width + x0) * channels + src_c;
261	                int idx01 = (y0 * width + x1) * channels + src_c;
262	                int idx10 = (y1 * width + x0) * channels + src_c;
263	                int idx11 = (y1 * width + x1) * channels + src_c;
264	
265	                float v00 = static_cast<float>(image_data[idx00]);
266	                float v01 = static_cast<float>(image_data[idx01]);
267	                float v10 = static_cast<float>(image_data[idx10]);
268	                float v11 = static_cast<float>(image_data[idx11]);
269	
270	                float v = v00 * (1 - dx) * (1 - dy) +
271	                          v01 * dx * (1 - dy) +
272	                          v10 * (1 - dx) * dy +
273	                          v11 * dx * dy;
274	
275	                v = (v / 255.0f - image_mean_[c]) / image_std_[c];
276	
277	                output.channel(c).row(y)[x] = v;
278	            }
279	        }
280	    }
281	
282	    return output;
283	}
