285	std::vector<float> ncnn_embedding::encode_text(const std::string& text) const {
286	    if (!ok_) {
287	        return {};
288	    }
289	
290	    std::vector<int> token_ids;
291	    if (unigram_tokenizer) {
292	        token_ids = unigram_tokenizer->encode(text, true, true);
293	    } else if (bpe_tokenizer) {
294	        token_ids = bpe_tokenizer->encode(text, false, false);
295	    }
296	
297	    int seq_len = static_cast<int>(token_ids.size());
298	    if (seq_len == 0) {
299	        return std::vector<float>(text_embed_dim_, 0.0f);
300	    }
301	
302	    if (seq_len > max_seq_len_) {
303	        token_ids.resize(max_seq_len_);
304	        seq_len = max_seq_len_;
305	    }
306	
307	    ncnn::Mat input_ids(seq_len, 1, 1);
308	    for (int i = 0; i < seq_len; ++i) {
309	        ((int*)input_ids.data)[i] = token_ids[i];
310	    }
311	
312	    ncnn::Mat cos_cache, sin_cache;
313	    if (rope_type_ == "RoPE_full") {
314	        generate_rope_embed_cache_full(seq_len, rope_head_dim_, 0, cos_cache, sin_cache, rope_theta_);
315	    } else {
316	        generate_rope_embed_cache(seq_len, rope_head_dim_, 0, cos_cache, sin_cache, rope_theta_);
317	    }
318	
319	    ncnn::Mat embeddings;
320	    {
321	        ncnn::Extractor ex = text_encoder_net->create_extractor();
322	        ex.input("in0", input_ids);
323	        ex.input("in1", cos_cache);
324	        ex.input("in2", sin_cache);
325	        ex.extract("out0", embeddings);
326	    }
327	
328	    if (embeddings.empty()) {
329	        fprintf(stderr, "Error: text encoder output is empty\n");
330	        return std::vector<float>(text_embed_dim_, 0.0f);
331	    }
332	
333	    ncnn::Mat result_mat;
334	    if (model_type_ == "clip") {
335	        result_mat = normalize(embeddings);
336	    } else {
337	        ncnn::Mat pooled = mean_pool(embeddings);
338	        result_mat = normalize(pooled);
339	    }
340	
341	    std::vector<float> result(text_embed_dim_);
342	    memcpy(result.data(), result_mat.data, text_embed_dim_ * sizeof(float));
343	
344	    return result;
345	}
346	
347	std::vector<std::vector<float>> ncnn_embedding::encode_text_batch(const std::vector<std::string>& texts) const {
348	    std::vector<std::vector<float>> results;
349	    results.reserve(texts.size());
350	    for (const auto& text : texts) {
351	        results.push_back(encode_text(text));
352	    }
353	    return results;
354	}
355	
356	std::vector<float> ncnn_embedding::encode_image(const std::vector<unsigned char>& image_data, int width, int height, int channels) const {
357	    if (!ok_ || !vision_encoder_net) {
358	        return {};
359	    }
360	
361	    ncnn::Mat pixel_values = preprocess_image(image_data, width, height, channels);
362	
363	    ncnn::Mat embedding;
364	    {
365	        ncnn::Extractor ex = vision_encoder_net->create_extractor();
366	        ex.input("in0", pixel_values);
367	        ex.extract("out0", embedding);
368	    }
369	
370	    if (embedding.empty()) {
371	        fprintf(stderr, "Error: vision encoder output is empty\n");
372	        return std::vector<float>(vision_embed_dim_, 0.0f);
373	    }
374	
375	    ncnn::Mat normalized = normalize(embedding);
376	
377	    std::vector<float> result(vision_embed_dim_);
378	    memcpy(result.data(), normalized.data, vision_embed_dim_ * sizeof(float));
379	
380	    return result;
381	}
382	
383	std::vector<float> ncnn_embedding::encode_image_file(const std::string& image_path) const {
384	    if (!ok_ || !vision_encoder_net) {
385	        return {};
386	    }
387	
388	    ncnn::Mat raw_image = load_image_to_ncnn_mat(image_path);
389	    if (ncnn_mat_empty(raw_image)) {
390	        fprintf(stderr, "Error: failed to load image %s\n", image_path.c_str());
391	        return std::vector<float>(vision_embed_dim_, 0.0f);
392	    }
393	
394	    int width = raw_image.w;
395	    int height = raw_image.h;
396	    std::vector<unsigned char> image_data(width * height * 3);
397	    unsigned char* src = (unsigned char*)raw_image.data;
398	    for (int i = 0; i < width * height; ++i) {
399	        image_data[i * 3 + 0] = src[i * 3 + 2];
400	        image_data[i * 3 + 1] = src[i * 3 + 1];
401	        image_data[i * 3 + 2] = src[i * 3 + 0];
402	    }
403	
404	    return encode_image(image_data, width, height, 3);
405	}

